def onLine (pt : Fin 7) (i : Fin 7) : Bool :=
  let (a, b, c) := fanoLine i
  pt == a || pt == b || pt == c

def formationTuple (s : SystemSpec) : FormationTuple :=
  { n1 := s.primitive_stage.count,
    n2 := s.transformation_stage.count,
    n3 := s.output_stage.count,
    n4 := s.interface_stage.count }

def formationTotal (s : SystemSpec) : Nat :=
  s.primitive_stage.count + s.transformation_stage.count +
  s.output_stage.count + s.interface_stage.count
